// BarCODE

let mySize;
let seed = Math.random() * 2000;
let tile_Count = 16;
let cubes = [];
let w;
// colors
let colors2 = "192985-8486e6-000000".split("-").map((a) => "#" + a);
// color #RRGGBBAA
let colors1 = "192985-8486e6-000000".split("-").map((a) => "#" + a);

function setup() {
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize);
	//randomSeed(seed);
	background(0);

	w = width / tile_Count;

	for (let i = 0; i < tile_Count; i++) {
		for (let j = 0; j < tile_Count; j++) {
			let scaleX = random(20);
			let scaleY = random(20);
			let x = i * w;
			let y = j * w;
			let ShapeItem = int(random(1, 2));
			if (ShapeItem == 1) {
				cubes.push(new makeCubes(x, y, w * scaleX, w * scaleY));
			}
		}
	}
}

function draw() {
	randomSeed(seed);
	background(0, 20);
	for (let c of cubes) {
		let numItem = int(random(0, 2));
		if (numItem == 1) {
			c.display1();
		} else {
			c.display2();
		}

	}
}

class makeCubes {
	constructor(x, y, wx, wy) {
		this.x = x;
		this.y = y;
		this.wx = wx;
		this.wy = wy;
		this.col1 = random(colors1);
		this.col2 = random(colors2);
		//this.strWei = random([1, 2, 4, 8, 16, 32]);
	}

	display1() {
		this.strWei = random([1, 2, 4, 8, 16, 32]);
		strokeWeight(this.strWei);
		//fill(this.col1);
		noFill();
		strokeCap(SQUARE);
		stroke(this.col1);
		let lineNum = int(w / (3 * this.strWei));
		for (let i = 0; i < lineNum + 1; i++) {
			line(
				this.x + i * 3 * this.strWei,
				this.y,
				this.x + i * 3 * this.strWei,
				this.y + this.wy
			);
		}
	}

	display2() {
		this.strWei = random([1, 2, 4, 8, 16, 32]);
		strokeWeight(this.strWei);
		//fill(this.col1);
		noFill();
		strokeCap(SQUARE);
		stroke(this.col1);
		var lineNum = int(w / (3 * this.strWei));
		for (let i = 0; i < lineNum + 1; i++) {
			line(
				this.x,
				this.y + i * 3 * this.strWei,
				this.x + this.wx,
				this.y + i * 3 * this.strWei
			);
		}
	}
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("BarCODE", "png");
	}
}

